# TEST FIXTURE (id 92): a second outdoor area (ruta_1) with nothing animated: the world must never wake for it (contract section 22).
# Its on_enter script just waits 600 ms: the banner must not start while a script runs.
@map test_zone_b
@size 10 8
@interior no
@bg 0
@area ruta_1
@fill grass_a
@spawn from_a 2 4 E
@legend
  .  tile=grass_a
  w  tile=mat
@grid
  ..........
  ..........
  ..........
  ..........
  .w........
  ..........
  ..........
  ..........
@warp w -> test_zone_a spawn=from_b
@script settle on_enter
    wait 600
@end
